import{z as l,x as B,o as r,c as d,q as o,j as i,D as t,d as E,s,S as m,b as e}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"连续时间预算约束","description":"","frontmatter":{"title":"连续时间预算约束","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/continuous-time-budget.md","filePath":"econ/continuous-time-budget.md","lastUpdated":1791413859000}'),A={name:"econ/continuous-time-budget.md"};function h(p,a,u,c,C,D){const n=B("Mermaid");return r(),d("div",null,[a[2]||(a[2]=o('<h1 id="连续时间预算约束" tabindex="-1">连续时间预算约束 <a class="header-anchor" href="#连续时间预算约束" aria-label="Permalink to &quot;连续时间预算约束&quot;">​</a></h1><div class="epigraph"><p>财富的微分等于资本利得加利息减消费；伊藤项让预算本身成为随机微分方程，而不是每期的算术和。</p><footer>—— 据 Merton, Optimum Consumption and Portfolio Rules in a Continuous-Time Model, JET 1971</footer></div><p><a href="/econ/brownian-ito">上一课</a>给出 \\(\\mathrm{d}f\\) 的公式。本课缺口是把公式写成<strong>预算</strong>：消费率 \\(c_t\\)、组合权重 \\(\\theta_t\\) 如何驱动 \\(W_t\\)。不求解最优，\\(\\theta\\) 与 \\(c\\) 仍是任意适应过程（满足正则）。后课 Merton 问题才对它们取最大值。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>离散： \\(W_{t+1}=(W_t-C_t)(1+R_{p,t+1})\\)。连续极限：设无风险 \\(r\\)，风险资产 \\(\\mathrm{d}S/S=\\mu\\mathrm{d}t+\\sigma\\mathrm{d}B\\)，权重 \\(\\theta\\) 在风险资产上，则</p> \\[\\mathrm{d}W=\\bigl[rW+\\theta W(\\mu-r)-c\\bigr]\\mathrm{d}t+\\theta W\\sigma\\,\\mathrm{d}B. \\]<p>这是状态的动力学。横截或非负财富排除加倍。缺口是承认：连续时间的可行性是对这道 SDE 的积分，消费是速率，组合是暴露。需求系统的「份额」在此变成 \\(\\theta\\)；没有特征 logit，只有暴露于 \\(B\\) 的系数。</p><p><span class="marginnote">术语翻译：「自融资」就是账户中间不转入也不转出钱——财富的变化全部来自资产价格变动，唯一的出口是消费 \\(c\\)。像炒股只调仓不追加保证金：亏了赚了都是市场给的，不是自己塞进去的。</span></p><p><span class="marginnote">Merton, <em>JET</em> 3, 1971。劳动收入、多个布朗、随机 \\(r\\)，只是把 \\(\\mathrm{d}W\\) 加项。本课先单一风险资产、常系数，便于看见结构。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>从自融资出发：除消费外没有注入，持仓的价值变化全部来自价格变化。伊藤乘法给出 \\(\\theta\\) 进入漂移与扩散的方式——扩散只被风险暴露驱动，消费只进漂移。这与 FTAP 衔接：\\(\\mathrm{d}W\\) 的扩散若能被 \\(\\theta\\) 对冲掉任意 \\(\\mathcal{F}\\)–适应的目标（在完全时），复制就是选 \\(\\theta\\)。预算是复制与最优的共同约束。</p>',11)),(r(),i(m,null,{default:t(()=>[s(n,{id:"mermaid-29",class:"mermaid",graph:"flowchart%20TD%0A%20%20SELF%5B%22%E8%87%AA%E8%9E%8D%E8%B5%84%22%5D%20--%3E%20SDE%5B%22dW%20%3D%20(rW%20%2B%20%CE%B8W(%CE%BC-r)%20-%20c)%20dt%20%2B%20%CE%B8W%CF%83%20dB%22%5D%0A%20%20SDE%20--%3E%20DRIFT%5B%22c%20%E4%B8%8E%E8%B6%85%E9%A2%9D%E5%8F%AA%E8%BF%9B%E6%BC%82%E7%A7%BB%22%5D%0A%20%20SDE%20--%3E%20DIFF%5B%22%CE%B8%20%E5%86%B3%E5%AE%9A%E6%89%A9%E6%95%A3%22%5D%0A%20%20DIFF%20--%3E%20NEXT%5B%22%E4%B8%8B%E4%B8%80%E8%AF%BE%3A%20%E9%80%89%20%CE%B8%20%E4%B8%8E%20c%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,"不要把 \\(\\mathrm{d}W\\) 写成每笔成交后的现金账户。连续时间没有逐笔：是理想化的再平衡。价差下再平衡有成本，Constantinides 后课把预算改成区间策略。本课零成本。",-1)),a[4]||(a[4]=e("h2",{id:"机制",tabindex:"-1"},[E("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=e("p",null,"机制是暴露与消耗分开记账。消费降低漂移，立刻减少未来投资的基数；风险暴露同时提高（或降低）漂移里的超额，并打开扩散。二次变差使 \\(W\\) 的凹变换（如 \\(\\log W\\)）多一项 \\(-\\tfrac12\\theta^2\\sigma^2\\)，即便 \\(\\mathrm{E}[\\mathrm{d}W]\\) 看起来很美。这就是后文最优会惩罚 \\(\\theta\\) 的原因——在预算里已经藏了 Jensen，不只在效用里。",-1)),(r(),i(m,null,{default:t(()=>[s(n,{id:"mermaid-39",class:"mermaid",graph:"flowchart%20TD%0A%20%20W%5B%22%E8%B4%A2%E5%AF%8C%20W(t)%22%5D%20--%3E%20C1%5B%22%E6%B6%88%E8%B4%B9%20c%EF%BC%9A%E5%8F%AA%E5%87%8F%E6%BC%82%E7%A7%BB%22%5D%0A%20%20W%20--%3E%20T1%5B%22%E9%A3%8E%E9%99%A9%E6%9A%B4%E9%9C%B2%20%CE%B8%EF%BC%9A%E5%8A%A0%E8%B6%85%E9%A2%9D%E6%BC%82%E7%A7%BB%22%5D%0A%20%20W%20--%3E%20T2%5B%22%CE%B8%CF%83%EF%BC%9A%E6%89%93%E5%BC%80%E6%89%A9%E6%95%A3%E9%A1%B9%22%5D%0A%20%20T1%20--%3E%20ITO%5B%22%E4%BC%8A%E8%97%A4%E9%A1%B9%EF%BC%9A%E5%87%B9%E5%8F%98%E6%8D%A2%E5%A4%9A%20%E2%88%92%C2%BD%CE%B8%C2%B2%CF%83%C2%B2%22%5D%0A%20%20T2%20--%3E%20ITO%0A%20%20ITO%20--%3E%20PEN%5B%22%E8%BF%87%E5%A4%A7%E7%9A%84%20%CE%B8%20%E5%9C%A8%E6%9C%80%E4%BC%98%E8%A7%A3%E4%B8%AD%E8%A2%AB%E6%83%A9%E7%BD%9A%22%5D%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=o('<p><span class="marginnote">数字实例：取 \\(\\theta\\sigma=20\\%\\)，则 \\(\\log W\\) 每年要白白付出 \\(\\tfrac12(0.20)^2=2\\%\\) 的「波动税」。也就是说，平均收益里看着多赚的 2 个百分点，一换成对数效用就被波动本身吃掉——这解释了为什么最优权重 \\(\\theta\\) 不会无限加大。</span></p><p>多个资产：\\(\\theta\\) 成向量，\\(\\sigma\\) 成矩阵，扩散维数等于独立布朗数。维数不够则预算张不成任意终端财富，回到动态不完全。维数对齐则本课的 SDE 是完全市场的预算。</p><p><span class="marginnote">常见误区：初学者容易把这道 SDE 当成「每期记账的极限求和」。连续时间里没有逐笔账本，只有漂移（平均变化率）与扩散（波动幅度）两个分量；「预算约束」的含义变成：沿这条随机微分方程积分出的路径不许为负，而不是某一天对不上账。</span></p><p><span class="marginnote">随机利率：债券价格也扩散，\\(W\\) 多暴露一项，后文对冲需求正是为了对付这项。本课 \\(r\\) 为常数，对冲还没有对象。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不谈存在唯一强解的 Lipschitz 条件。下一课在这道预算上最大化 \\(\\mathrm{E}\\int u(c)\\,\\mathrm{d}t\\)（加遗产），得到 Merton 权重。ICAPM 主干课已经用过对冲的结果；本单元从预算重新走到那条结果，并停在组合理论，不重写截面因子。</p><p>后课默认：连续时间预算是自融资 SDE；消费进漂移，组合进漂移与扩散。财富下界排除加倍。零交易成本。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>\\(\\mathrm{d}W=[rW+\\theta W(\\mu-r)-c]\\mathrm{d}t+\\theta W\\sigma\\mathrm{d}B\\)。</li><li>自融资：无注入；扩散由风险暴露单独决定。</li><li>这是最优与复制的共同约束，还不是最优。</li><li>出处：Merton, <em>JET</em> 1971。</li></ul>',9))])}const g=l(A,[["render",h]]);export{_ as __pageData,g as default};
